(() => {
  'use strict';
  const KEY = 'daily-checkin:admin-prototype:v1';
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
    coins:'M20 7c0 2.2-3.6 4-8 4s-8-1.8-8-4 3.6-4 8-4 8 1.8 8 4ZM4 7v5c0 2.2 3.6 4 8 4s8-1.8 8-4V7M4 12v5c0 2.2 3.6 4 8 4s8-1.8 8-4v-5',
    rules:'M4 7h16M4 17h16M8 4v6M16 14v6',
    history:'M3 12a9 9 0 1 0 2.6-6.4L3 8M3 3v5h5M12 7v5l3 2',
    shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7l-9-4ZM8 12l3 3 5-6',
    search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
    plus:'M12 5v14M5 12h14',
    arrow:'M5 12h14m-5-5 5 5-5 5',
    chevron:'m9 5 7 7-7 7',
    close:'m6 6 12 12M6 18 18 6',
    warning:'m12 3 10 18H2L12 3ZM12 9v4M12 17h.01',
    check:'m5 12 4 4L19 6',
    calendar:'M8 2v4M16 2v4M3 10h18M4 4h16a1 1 0 0 1 1 1v15a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1ZM8 15h2M14 15h2',
    info:'M12 8h.01M12 11v6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    refresh:'M20 7a9 9 0 0 0-15-2L2 8M2 3v5h5M4 17a9 9 0 0 0 15 2l3-3M17 16h5v5',
    lock:'M5 10h14v11H5V10ZM8 10V6a4 4 0 0 1 8 0v4M12 14v3',
    mail:'M3 5h18v14H3V5Zm0 1 9 7 9-7',
    grid:'M3 3h7v7H3V3ZM14 3h7v7h-7V3ZM3 14h7v7H3v-7ZM14 14h7v7h-7v-7'
  };
  const icon = name => `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[name] || paths.grid}"/></svg></span>`;
  const badge = (text, type='') => `<span class="badge ${type}">${esc(text)}</span>`;
  const now = () => new Date().toLocaleString('sv-SE', {timeZone:'Asia/Shanghai'});
  const cap = u => u.free + u.purchased;
  const used = u => u.accounts.filter(a => a.auto).length;
  const attention = u => u.status === 'active' && u.accounts.some(a => a.auto && ['expired','failed'].includes(a.state));
  const signed = u => u.accounts.filter(a => a.state === 'signed').length;
  const stateLabel = state => ({signed:'已签到',expired:'登录失效',failed:'执行失败',pending:'待签到',idle:'待开启'})[state] || '待确认';
  const stateTone = state => ({signed:'',expired:'bad',failed:'warn',pending:'blue',idle:'muted'})[state] || 'muted';

  function seed() {
    const rows = [
      ['linxiaoyu','小雨','li***@qq.com',30,0,['signed','signed'],true],
      ['chenchen','晨晨','ch***@163.com',20,1,['signed','expired','signed'],true],
      ['zhouyue','周悦','zy***@qq.com',5,0,['signed','signed'],true],
      ['xiaolu','小鹿','xl***@qq.com',50,2,['signed','signed','signed','signed'],true],
      ['momo','默默','mo***@163.com',0,0,['failed','signed'],true],
      ['wangan','晚安','wa***@qq.com',10,0,['pending','idle'],true],
      ['tangtang','糖糖','ta***@qq.com',15,0,['signed'],true],
      ['shanyue','山月','sy***@163.com',0,0,['expired','signed'],true],
      ['huli','狐狸','hu***@qq.com',40,1,['signed','signed','idle'],false],
      ['yimu','一木','ym***@163.com',10,0,['signed','idle'],true],
      ['xiaohe','小禾','xh***@qq.com',0,0,[],true],
      ['qingfeng','清风','qf***@163.com',20,0,['pending'],false]
    ];
    const users = rows.map((r,i) => ({id:1001+i,username:r[0],name:r[1],email:r[2],points:r[3],free:2,purchased:r[4],status:r[6]?'active':'disabled',
      created:`2026-10-${String(15+i%5).padStart(2,'0')} 10:20`,last:`2026-10-${i>7?'25':'26'} ${String(14-i%6).padStart(2,'0')}:${String(38-i).padStart(2,'0')}`,
      mail:i!==10,push:[0,1,3,6].includes(i),success:true,failure:true,note:i===1?'家庭账号较多，关注小程序登录有效期。':'',
      accounts:r[5].map((state,j)=>({id:`a-${i}-${j}`,name:['主号','家人号','备用号','工作号'][j],channel:j%2?'龙湖小程序':'龙湖 App',auto:state!=='idle',state,signTime:'09:10',checkTime:'16:00'}))}));
    const ledger=[];
    for (const u of users) {
      if (u.points+u.purchased*10) ledger.push({id:`P-${u.id}-1`,userId:u.id,type:'grant',delta:u.points+u.purchased*10,balance:u.points+u.purchased*10,time:'2026-10-23 10:20',actor:'admin',reason:'体验积分发放',related:'—'});
      for(let j=0;j<u.purchased;j++) ledger.push({id:`P-${u.id}-${j+2}`,userId:u.id,type:'purchase',delta:-10,balance:u.points+(u.purchased-j-1)*10,time:`2026-10-24 11:${String(j+10).padStart(2,'0')}`,actor:u.username,reason:'购买 1 个自动打卡名额',related:`Q-${u.id}-${j+1}`});
    }
    return {version:1,users,ledger,audit:[{id:'A-1',userId:1009,type:'用户停用',actor:'admin',reason:'用户申请暂停使用，保留账号与已购买名额。',time:'2026-10-25 16:30'},{id:'A-2',userId:1012,type:'用户停用',actor:'admin',reason:'测试用户，暂时停用。',time:'2026-10-25 15:20'}],rules:{free:2,price:10},registration:true};
  }
  function load() {try {const d=JSON.parse(localStorage.getItem(KEY));if(d?.version===1 && Array.isArray(d.users) && Array.isArray(d.ledger) && d.rules)return d;}catch(_){}return seed();}
  let db=load(), page='users', filter='all', search='', stateFilter='all', order='recent', pageNum=1, selected=new Set(), drawerId=null, drawerTab='overview', lastTrigger=null, modalSubmit=null, toastTimer;
  const PAGE_SIZE=6;
  function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch(_){toast('当前浏览器未允许本地保存，刷新后会恢复示例。');}}
  function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').classList.add('visible');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3600);}
  function audit(userId,type,reason,actor='admin'){db.audit.unshift({id:'A-'+crypto.randomUUID().slice(0,8),userId,type,actor,reason,time:now()});}
  function addLedger(u,type,delta,reason,actor='admin',related='—'){u.points+=delta;const row={id:'P-'+crypto.randomUUID().slice(0,8).toUpperCase(),userId:u.id,type,delta,balance:u.points,time:now(),actor,reason,related};db.ledger.unshift(row);return row;}
  const user = id => db.users.find(u=>u.id===Number(id));
  const title = (label,description,actions='')=>`<section class="heading"><div><p class="eyebrow">DAILY CHECK-IN / ADMIN</p><h1>${label}</h1><p class="subtle">${description}</p></div><div class="heading-actions">${actions}</div></section>`;

  function nav(){
    const labels={users:'用户管理',ledger:'积分流水',rules:'积分与名额',audit:'操作记录'};
    $('breadcrumb').textContent=labels[page];document.title=labels[page]+' · 每日签到原型';
    const links=Object.entries(labels).map(([key,label])=>`<a href="#${key}" ${page===key?'aria-current="page"':''}>${icon({users:'users',ledger:'coins',rules:'rules',audit:'history'}[key])}<span class="nav-text">${label}</span>${key==='users'?`<span class="nav-badge">${db.users.length}</span>`:''}</a>`).join('');
    $('navigation').innerHTML=links;$('mobile-navigation').innerHTML=links;
  }
  function stat(label,value,caption,symbol,extra='',action=''){return `<${action?'button':'div'} class="stat ${extra}" ${action?`data-action="${action}"`:''}><span class="stat-label">${label}${icon(symbol)}</span><strong>${value}</strong><small>${caption}</small></${action?'button':'div'}>`;}
  function usersPage(){
    const active=db.users.filter(u=>u.status==='active'), running=db.users.reduce((n,u)=>n+used(u),0), total=db.users.reduce((n,u)=>n+cap(u),0);
    return `${title('用户管理','把用户状态、自动打卡名额和积分，放在一起管理。',`<button class="secondary-action" data-action="goto-rules">${icon('rules')}权益规则</button><button class="primary" data-action="create">${icon('plus')}新增用户</button>`)}
      <div class="stats">${stat('用户总数',db.users.length,`正常 ${active.length} · 已停用 ${db.users.length-active.length}`,'users','active','filter-all')}${stat('需要关注',db.users.filter(attention).length,'登录失效或执行失败的用户','warning','attention','filter-attention')}${stat('自动打卡名额',`${running}<small> / ${total}</small>`,'已占用 / 已分配名额','calendar')}${stat('用户积分余额',db.users.reduce((n,u)=>n+u.points,0),'可用于购买更多自动打卡名额','coins')}</div>
      <div class="policy-strip"><span class="policy-symbol">${icon('coins')}</span><div class="policy-copy"><strong>默认 ${db.rules.free} 个免费名额</strong><span class="divider">/</span><strong>${db.rules.price} 积分增加 1 个名额</strong><small>购买时扣一次积分，已购名额长期保留；暂停签到账号可释放占用。</small></div><button class="link" data-action="goto-rules">查看规则 ${icon('arrow')}</button></div>
      <section class="panel" aria-label="用户列表"><div class="panel-top"><div class="tabs" role="tablist" aria-label="用户分类">${[['all','全部用户',db.users.length],['attention','需要关注',db.users.filter(attention).length],['active','正常使用',active.length],['disabled','已停用',db.users.length-active.length]].map(([key,label,count])=>`<button role="tab" class="tab" data-filter="${key}" aria-selected="${filter===key}">${label}<small>${count}</small></button>`).join('')}</div><div class="registration"><span><i class="dot" style="${db.registration?'':'background:#9aaba0'}"></i>${db.registration?'注册已开放':'注册已关闭'}</span><button class="link" data-action="registration">${db.registration?'关闭注册':'开放注册'}</button></div></div>
      <div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">搜索用户</span><input id="user-search" type="search" placeholder="搜索用户名、昵称、用户 ID" value="${esc(search)}" autocomplete="off"></label><label class="select-wrap"><span>签到状态</span><select id="state-filter" aria-label="签到状态"><option value="all">全部签到状态</option><option value="expired">登录失效</option><option value="failed">执行失败</option><option value="full">名额已用满</option><option value="low">积分不足以扩容</option><option value="empty">尚未添加账号</option></select></label><label class="select-wrap"><span class="sr-only">排序</span><select id="user-order" aria-label="用户排序"><option value="recent">最近活跃</option><option value="points">积分从低到高</option><option value="quota">已购名额最多</option></select></label><span class="toolbar-spacer"></span><span class="results-count" id="results-count"></span></div>
      <div id="bulk-area"></div><div class="table-wrap"><table><thead><tr><th><label class="checkbox-hit"><input type="checkbox" id="select-page" aria-label="选择当前页用户"></label></th><th>用户</th><th>账号状态</th><th>自动打卡名额</th><th>积分余额</th><th>今日签到</th><th class="activity-col">最近活跃</th><th class="right">操作</th></tr></thead><tbody id="user-rows"></tbody></table><div id="empty-users" hidden></div></div><div class="pagination" id="pagination"></div></section>
      <p class="after-note">${icon('info')}本站账号停用会暂停该用户的自动任务；龙湖登录失效仅影响对应签到账号。积分调整、名额扩容均保留流水。</p>`;
  }
  function filteredUsers(){return db.users.filter(u=>(filter==='all'||filter==='attention'&&attention(u)||filter==='active'&&u.status==='active'||filter==='disabled'&&u.status==='disabled')&&(!search||[u.username,u.name,u.id,u.email].some(v=>String(v).toLowerCase().includes(search.toLowerCase())))&&(stateFilter==='all'||stateFilter==='expired'&&u.accounts.some(a=>a.state==='expired')||stateFilter==='failed'&&u.accounts.some(a=>a.state==='failed')||stateFilter==='full'&&used(u)>=cap(u)||stateFilter==='low'&&u.points<db.rules.price||stateFilter==='empty'&&!u.accounts.length)).sort((a,b)=>order==='points'?a.points-b.points:order==='quota'?b.purchased-a.purchased:b.last.localeCompare(a.last));}
  function renderRows(){
    const rows=filteredUsers(), pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));pageNum=Math.min(pageNum,pages);
    const visible=rows.slice((pageNum-1)*PAGE_SIZE,pageNum*PAGE_SIZE);
    $('user-rows').innerHTML=visible.map((u,i)=>`<tr><td><label class="checkbox-hit"><input type="checkbox" data-select="${u.id}" aria-label="选择 ${esc(u.username)}" ${selected.has(u.id)?'checked':''}></label></td><td class="user-col"><div class="user-cell"><span class="avatar ${i%3===1?'warm':i%3===2?'blue':''}">${esc(u.name.slice(0,1))}</span><div class="user-info"><strong>${esc(u.username)}</strong><small>${esc(u.name)} · ID ${u.id}</small></div></div></td><td class="status-col">${badge(u.status==='disabled'?'已停用':attention(u)?'需要关注':'正常',u.status==='disabled'?'muted':attention(u)?'warn':'')}<span class="cell-sub">${u.status==='disabled'?'自动任务已暂停':attention(u)?u.accounts.some(a=>a.state==='expired')?'龙湖登录失效':'签到执行失败':'使用中'}</span></td><td class="quota-col"><span class="quota-number">${used(u)} <span>/ ${cap(u)}</span></span><span class="cell-sub">免费 ${u.free}${u.purchased?` + 已购 ${u.purchased}`:''}</span><div class="quota-track"><i style="width:${cap(u)?used(u)/cap(u)*100:0}%"></i></div></td><td class="points-col"><span class="points">${u.points} <small>积分</small></span><span class="cell-sub">${u.points<db.rules.price?'余额不足以扩容':`可增 ${Math.floor(u.points/db.rules.price)} 个名额`}</span></td><td class="result-col">${u.status==='disabled'?badge('已暂停','muted'):!u.accounts.length?badge('待添加','muted'):badge(`${signed(u)} / ${u.accounts.length} 已签到`,signed(u)===u.accounts.length?'':attention(u)?'warn':'blue')}<span class="cell-sub">${u.mail?'邮箱已验证':'通知未配置'}${u.push?' · 微信已订阅':''}</span></td><td class="activity-col"><span>${u.last.slice(5)}</span><span class="cell-sub">北京时间</span></td><td class="action-col right"><button class="link table-action" data-detail="${u.id}" aria-label="管理 ${esc(u.username)}">管理 ${icon('chevron')}</button></td></tr>`).join('');
    $('results-count').textContent=`共 ${rows.length} 位用户`;
    $('empty-users').hidden=!!rows.length;
    $('empty-users').innerHTML=rows.length?'':`<div class="empty">${icon('search')}<h3>没有找到符合条件的用户</h3><p>试试其他用户名，或清除当前筛选。</p><button data-action="clear-filters">清除筛选</button></div>`;
    $('pagination').innerHTML=`<span>${rows.length?`${(pageNum-1)*PAGE_SIZE+1}–${Math.min(pageNum*PAGE_SIZE,rows.length)}`:'0'} / ${rows.length} 位用户 · 每页 ${PAGE_SIZE} 位</span><div class="pagination-controls"><button data-page="${pageNum-1}" ${pageNum===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${pageNum===i+1?'current':''}" ${pageNum===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${pageNum+1}" ${pageNum===pages?'disabled':''} aria-label="下一页">›</button></div>`;
    const all=!!visible.length&&visible.every(u=>selected.has(u.id));$('select-page').checked=all;$('select-page').indeterminate=!all&&visible.some(u=>selected.has(u.id));
    $('bulk-area').innerHTML=selected.size?`<div class="bulkbar"><span>已选择 <strong>${selected.size}</strong> 位用户</span><button data-action="bulk-points">${icon('coins')}批量发积分</button><button data-action="bulk-disable">停用所选用户</button><button class="link" data-action="clear-selection">取消选择</button></div>`:'';
  }

  const ledgerTypes={grant:'管理员发放',deduct:'管理员扣减',purchase:'名额扩容'};
  function ledgerRows(rows){return rows.sort((a,b)=>b.time.localeCompare(a.time)).map(r=>`<tr><td>${esc(user(r.userId)?.username||'用户已移除')}<span class="cell-sub">${esc(r.id)}</span></td><td data-label="变动类型">${badge(ledgerTypes[r.type],r.type==='purchase'?'blue':r.type==='deduct'?'warn':'')}</td><td data-label="积分变动"><span class="ledger-delta ${r.delta<0?'negative':''}">${r.delta>0?'+':''}${r.delta}</span></td><td data-label="变动后余额">${r.balance}</td><td data-label="说明">${esc(r.reason)}<span class="cell-sub">操作人：${esc(r.actor)}${r.related!=='—'?` · ${esc(r.related)}`:''}</span></td><td data-label="时间">${esc(r.time.slice(5))}</td></tr>`).join('');}
  function ledgerPage(){return `${title('积分流水','每一笔发放、扣减和扩容，都有明确去向。')}<section class="panel"><div class="table-heading"><h2>全部积分变动 <span class="subtle">${db.ledger.length} 笔</span></h2></div><div class="toolbar"><label class="search">${icon('search')}<span class="sr-only">搜索积分流水</span><input type="search" id="ledger-search" placeholder="搜索用户名或变动说明"></label><label class="select-wrap"><span>类型</span><select id="ledger-type"><option value="all">全部变动类型</option><option value="grant">管理员发放</option><option value="deduct">管理员扣减</option><option value="purchase">名额扩容</option></select></label></div><table class="ledger-table"><thead><tr><th>用户 / 流水号</th><th>类型</th><th>积分变动</th><th>变动后余额</th><th>说明 / 操作人</th><th>北京时间</th></tr></thead><tbody id="ledger-rows">${ledgerRows([...db.ledger])}</tbody></table><div class="empty" id="ledger-empty" hidden><h3>没有符合条件的流水</h3><p>调整搜索词或变动类型后重试。</p></div></section><p class="after-note">${icon('info')}流水记录保留每次变动后的余额。原型中只演示管理员发放，不接入充值或支付。</p>`;}
  function auditPage(){const rows=[...db.audit].sort((a,b)=>b.time.localeCompare(a.time));return `${title('操作记录','查看谁在什么时间，对哪位用户做了什么。')}<section class="panel"><div class="table-heading"><h2>管理员操作 <span class="subtle">${rows.length} 条</span></h2><p class="subtle" style="margin:7px 0 18px">积分变动的金额与余额，请在积分流水中查看。</p></div><table class="audit-table"><thead><tr><th>操作对象</th><th>操作内容</th><th>原因 / 说明</th><th>操作人</th><th>北京时间</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.userId?esc(user(r.userId)?.username||'用户已移除'):'平台设置'}<span class="cell-sub">${esc(r.id)}</span></td><td data-label="操作内容">${esc(r.type)}</td><td data-label="原因 / 说明">${esc(r.reason)}</td><td data-label="操作人">${esc(r.actor)}</td><td data-label="北京时间">${esc(r.time.slice(5))}</td></tr>`).join('')}</tbody></table></section>`;}
  function rulesPage(){return `${title('积分与名额','先把权益规则定清楚，用户扩容时就能明白地确认。')}<div class="rules-grid"><section class="panel rules-card"><h2>自动打卡权益</h2><p class="subtle">免费名额适用于每位新用户，App 与小程序合计计算。</p><form id="rules-form"><label for="rule-free">新用户免费名额</label><div class="input-unit"><input id="rule-free" name="free" type="number" min="0" max="20" step="1" value="${db.rules.free}" required><span>个 / 用户</span></div><p class="subtle">只对之后新增的用户生效，已有用户的免费名额保持原值。</p><label for="rule-price">新增 1 个名额所需积分</label><div class="input-unit"><input id="rule-price" name="price" type="number" min="1" max="10000" step="1" value="${db.rules.price}" required><span>积分 / 个</span></div><p class="subtle">只影响之后的扩容；已购买名额不补扣积分。</p><label>积分来源</label><div class="notice">第一版由管理员手动发放，支持备注原因及批量发放。后续可再增加邀请奖励、任务奖励或充值。</div><div class="actions"><button class="primary" type="submit">保存权益规则</button><button type="button" data-action="demo-purchase-default">体验用户扩容</button></div><p class="error" id="rules-error" role="alert"></p></form></section><aside class="panel rules-card"><h2>用户会经历什么</h2>${[['使用免费自动名额',`新用户默认有 ${db.rules.free} 个免费名额，在额度内直接开启。`],['名额已满时申请新增',`确认扣除 ${db.rules.price} 积分，永久增加 1 个名额。`],['积分不足时', '展示余额与缺口，提示联系管理员获取积分。'],['暂停或移除签到账号', '释放占用，已购买名额保留，可给其他账号使用。']].map(([a,b],i)=>`<div class="rule-flow"><span class="step-number">${i+1}</span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}<div class="notice" style="margin:20px 0 0">只在扩容时扣分，每日执行签到不扣分。恢复已有名额内的自动计划，也不会再次扣分。</div></aside></div>`;}
  function render(){nav();$('main').innerHTML=page==='users'?usersPage():page==='ledger'?ledgerPage():page==='rules'?rulesPage():auditPage();if(page==='users'){$('state-filter').value=stateFilter;$('user-order').value=order;renderRows();}}
  function refreshViews(){save();render();if(drawerId&&$('user-drawer').open)renderDrawer();}
  function drawOverview(u){return `<div class="balance-card"><div><p>可用积分</p><strong>${u.points}<small>积分</small></strong></div><button data-action="points" data-user="${u.id}">${icon('plus')}调整积分</button></div><section class="quota-card"><div class="section-row"><h3>自动打卡名额</h3><button class="link" data-action="quota" data-user="${u.id}">调整免费名额</button></div><div class="quota-split"><div><strong>${used(u)}<small class="subtle"> / ${cap(u)}</small></strong><span>已占用 / 总名额</span></div><div><strong>${u.free}</strong><span>免费名额</span></div><div><strong>${u.purchased}</strong><span>已购名额</span></div></div><div class="wide-track"><span style="width:${cap(u)?used(u)/cap(u)*100:0}%"></span></div><p class="subtle">每次扩容 ${db.rules.price} 积分；暂停签到账号释放占用，已购名额保留。</p><button class="link" data-action="purchase" data-user="${u.id}" style="margin:9px 0 -4px;padding-left:0">体验用户扩容 ${icon('arrow')}</button></section><section class="detail-section"><h3>通知与账号</h3><div class="facts"><div class="fact"><span>本站账号状态</span><strong>${u.status==='disabled'?'已停用 · 自动任务暂停':'正常使用'}</strong></div><div class="fact"><span>注册时间</span><strong>${esc(u.created)}</strong></div><div class="fact"><span>接收邮箱</span><strong>${esc(u.email||'尚未配置')} ${u.mail?'· 已验证':''}</strong></div><div class="fact"><span>微信推送</span><strong>${u.push?'已绑定并订阅':'尚未订阅'}</strong></div><div class="fact"><span>提醒偏好</span><strong>${[u.success?'签到成功':'',u.failure?'失败或登录失效':''].filter(Boolean).join('、')||'均已关闭'}</strong></div><div class="fact"><span>最近活跃</span><strong>${esc(u.last)}</strong></div></div></section><form class="note-form" id="note-form"><label for="user-note">管理员备注</label><textarea id="user-note" maxlength="300" placeholder="记录处理进展或用户特殊情况…">${esc(u.note)}</textarea><div class="section-row"><p class="subtle">仅管理员可见</p><button type="submit">保存备注</button></div></form>`;}
  function drawAccounts(u){return `<div class="section-row" style="margin-bottom:15px"><h3>签到账号 <span class="subtle">${u.accounts.length} 个</span></h3><button class="link" data-action="add-demo-account" data-user="${u.id}">添加演示账号</button></div><p class="subtle">可体验用户开启或暂停自动打卡，只有占用超出名额时才需要扩容。</p>${u.status==='disabled'?'<div class="notice warn">该用户已停用，以下自动计划均暂停执行。恢复后继续按原计划运行。</div>':''}${u.accounts.length?u.accounts.map(a=>`<article class="account-card"><div class="section-row"><strong>${esc(a.channel)} · ${esc(a.name)}</strong>${badge(stateLabel(a.state),stateTone(a.state))}</div><div class="account-info"><span>${a.auto?'占用 1 个自动名额':'自动打卡未开启'}<br>签到 ${a.signTime} · 复核 ${a.checkTime}</span><span>${a.state==='expired'?'需由用户更新龙湖登录':a.state==='failed'?'本轮失败，等待下一轮复核':a.auto?'按计划运行':'未安排自动任务'}</span></div><div class="account-actions" style="margin-top:12px;text-align:right"><button data-action="toggle-auto" data-user="${u.id}" data-account="${a.id}" ${u.status==='disabled'?'disabled':''}>${a.auto?'暂停':'开启'}${esc(a.name)}自动打卡</button></div></article>`).join(''):`<div class="empty">${icon('grid')}<h3>还没有签到账号</h3><p>用户添加自己的龙湖账号后，会显示在这里。</p></div>`}<p class="after-note">${icon('shield')}管理员查看运行摘要；更新龙湖登录由用户本人完成。</p>`;}
  function drawUserLedger(u){const rows=db.ledger.filter(r=>r.userId===u.id).sort((a,b)=>b.time.localeCompare(a.time));return `<div class="section-row" style="margin-bottom:20px"><h3>积分变动 <span class="subtle">${rows.length} 笔</span></h3><button class="link" data-action="points" data-user="${u.id}">调整积分</button></div>${rows.length?rows.map(r=>`<div class="timeline-item"><span class="timeline-dot"></span><div><div class="section-row"><strong>${esc(r.reason)}</strong><span class="ledger-delta ${r.delta<0?'negative':''}">${r.delta>0?'+':''}${r.delta}</span></div><p>${ledgerTypes[r.type]} · 余额 ${r.balance} 积分 · ${esc(r.actor)}</p><time>${esc(r.time)} · ${esc(r.id)}</time></div></div>`).join(''):'<div class="empty"><h3>暂无积分变动</h3><p>管理员发放积分后，记录会显示在这里。</p></div>'}`;}
  function drawUserAudit(u){const rows=db.audit.filter(r=>r.userId===u.id).sort((a,b)=>b.time.localeCompare(a.time));return rows.length?rows.map(r=>`<div class="timeline-item"><span class="timeline-dot"></span><div><strong>${esc(r.type)}</strong><p>${esc(r.reason)}</p><time>${esc(r.time)} · ${esc(r.actor)}</time></div></div>`).join(''):'<div class="empty">'+icon('history')+'<h3>暂无管理操作</h3><p>调整权益、停用或恢复等操作会记录在这里。</p></div>';}
  function renderDrawer(){const u=user(drawerId);if(!u)return;$('user-drawer').innerHTML=`<header class="drawer-header"><div class="drawer-heading"><span class="avatar">${esc(u.name.slice(0,1))}</span><div><h2 id="drawer-name">${esc(u.username)}</h2><small>${esc(u.name)} · 用户 ID ${u.id}</small></div><button class="icon-button" data-action="close-drawer" aria-label="关闭用户详情">${icon('close')}</button></div><div class="tags">${badge(u.status==='disabled'?'账号已停用':'账号正常',u.status==='disabled'?'muted':'')}${attention(u)?badge('有签到异常','warn'):''}${badge('普通用户','blue')}</div></header><div class="tabs drawer-tabs" role="tablist" aria-label="用户详情分类">${[['overview','概览与权益'],['accounts','签到账号'],['ledger','积分流水'],['audit','操作记录']].map(([key,label])=>`<button class="tab" role="tab" aria-selected="${drawerTab===key}" data-drawer-tab="${key}">${label}</button>`).join('')}</div><div class="drawer-body">${drawerTab==='overview'?drawOverview(u):drawerTab==='accounts'?drawAccounts(u):drawerTab==='ledger'?drawUserLedger(u):drawUserAudit(u)}</div><footer class="drawer-footer"><button data-action="recovery" data-user="${u.id}">${icon('lock')}重置本站登录</button><button data-action="revoke" data-user="${u.id}">退出所有设备</button><button class="link" data-action="status" data-user="${u.id}">${u.status==='disabled'?'恢复用户':'停用用户'}</button></footer>`;}
  function openDrawer(id){drawerId=Number(id);drawerTab='overview';lastTrigger=document.activeElement;renderDrawer();$('user-drawer').showModal();}
  function closeDrawer(){$('user-drawer').close();drawerId=null;if(lastTrigger?.isConnected)lastTrigger.focus();}
  function modal(heading,body,buttonLabel,onSubmit,danger=false){modalSubmit=onSubmit;$('action-dialog').innerHTML=`<form id="modal-form"><div class="modal-head"><h2 id="action-title">${heading}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div>${body}<p class="error" id="modal-error" role="alert"></p><div class="actions"><button type="button" data-action="close-modal">取消</button><button type="submit" class="${danger?'danger':'primary'}" id="modal-confirm">${buttonLabel}</button></div></form>`;if(!$('action-dialog').open)$('action-dialog').showModal();}
  function closeModal(){$('action-dialog').close();modalSubmit=null;}
  const reasonField = (placeholder='填写本次调整原因，便于后续追溯')=>`<label class="field-label" for="action-reason">操作原因 <span class="subtle">必填</span></label><textarea id="action-reason" name="reason" required maxlength="200" placeholder="${placeholder}"></textarea>`;
  function pointsModal(ids){const targets=ids.map(user).filter(Boolean),one=targets.length===1,u=targets[0];if(!targets.length)return;modal(one?'调整用户积分':'批量发放积分',`<p class="subtle">${one?`${esc(u.username)} 当前余额 <strong>${u.points}</strong> 积分。`:`将给选中的 <strong>${targets.length}</strong> 位用户各发放相同数量的积分。`}</p>${one?'<div class="choice-row"><label><input type="radio" name="direction" value="grant" checked> 增加积分</label><label><input type="radio" name="direction" value="deduct"> 扣减积分</label></div>':''}<label class="field-label" for="points-amount">${one?'变动积分':'每人发放积分'}</label><input id="points-amount" name="amount" type="number" min="1" max="100000" step="1" value="10" required>${reasonField()}`,'确认调整',data=>{const n=Number(data.get('amount')),reason=String(data.get('reason')).trim(),type=data.get('direction')==='deduct'?'deduct':'grant';if(!Number.isSafeInteger(n)||n<1||n>100000)return '请输入 1–100000 的整数积分。';if(!reason)return '请填写操作原因。';if(type==='deduct'&&targets.some(t=>t.points<n))return '扣减数量超过可用余额，请重新填写。';targets.forEach(t=>{addLedger(t,type,type==='grant'?n:-n,reason);audit(t.id,type==='grant'?'发放积分':'扣减积分',`${type==='grant'?'+':'−'}${n} 积分；${reason}`);});closeModal();refreshViews();toast(one?'积分已调整，变动已记入流水。':`已向 ${targets.length} 位用户各发放 ${n} 积分。`);});}
  function statusModal(ids){const targets=ids.map(user).filter(Boolean),restore=targets.length===1&&targets[0].status==='disabled',eligible=targets.filter(t=>restore||t.status==='active');if(!eligible.length){toast('所选用户均已停用。');return;}modal(restore?'恢复用户？':eligible.length===1?'停用用户？':`停用 ${eligible.length} 位用户？`,`<p class="subtle">${restore?'恢复后允许本站登录，自动任务继续按原计划运行。':'停用后将退出本站登录并暂停该用户的全部自动任务。账号、积分和已购买名额会保留。'}</p><div class="notice ${restore?'':'warn'}">${eligible.map(t=>esc(t.username)).join('、')}</div>${reasonField(restore?'例如：用户已确认恢复使用':'例如：用户申请暂停使用')}`,restore?'确认恢复':'确认停用',data=>{const reason=String(data.get('reason')).trim();if(!reason)return '请填写操作原因。';eligible.forEach(t=>{t.status=restore?'active':'disabled';audit(t.id,restore?'恢复用户':'停用用户',reason);});closeModal();selected.clear();refreshViews();toast(restore?'用户已恢复。':'用户已停用，自动任务已暂停。');},!restore);}
  function quotaModal(u){const min=Math.max(0,used(u)-u.purchased);modal('调整免费名额',`<p class="subtle">${esc(u.username)} 当前免费 ${u.free} 个、已购 ${u.purchased} 个，已占用 ${used(u)} 个。</p><label class="field-label" for="free-quota">免费名额</label><input id="free-quota" name="free" type="number" min="${min}" max="100" step="1" value="${u.free}" required><p class="help">至少 ${min} 个，保证总名额不低于当前占用。已购名额保持不变。</p>${reasonField()}`,'保存名额',data=>{const n=Number(data.get('free')),reason=String(data.get('reason')).trim();if(!Number.isSafeInteger(n)||n<min||n>100)return `请填写 ${min}–100 之间的整数。`;if(!reason)return '请填写操作原因。';const old=u.free;u.free=n;audit(u.id,'调整免费名额',`${old} → ${n} 个；${reason}`);closeModal();refreshViews();toast('免费名额已更新。');});}
  function purchaseModal(u){
    if(u.status==='disabled'){modal('账号已停用','<p class="subtle">该用户已停用，恢复后才能购买新增名额。</p>','查看用户',()=>{closeModal();if(!$('user-drawer').open)openDrawer(u.id);});return;}
    const price=db.rules.price, can=u.points>=price;
    modal('增加自动打卡名额',`<p class="subtle">用户端体验 · ${esc(u.username)}<br>名额可用于龙湖 App 或小程序，每个开启自动打卡的账号占用 1 个名额。</p><div class="purchase-summary"><div><span>当前名额</span><strong>${used(u)} 个已用 / 共 ${cap(u)} 个</strong></div><div><span>本次增加</span><strong>1 个永久名额</strong></div><div><span>可用积分</span><strong>${u.points} 积分</strong></div><div class="total"><span>本次消耗</span><strong>${price} 积分</strong></div>${can?`<div><span>扩容后</span><strong>${cap(u)+1} 个名额 · 余额 ${u.points-price} 积分</strong></div>`:''}</div>${can?'<p class="help">确认后扣分一次；每日签到不扣分，暂停后可重复使用名额。</p>':`<div class="notice warn">积分不足，还差 ${price-u.points} 积分。请联系管理员获取积分后再扩容。</div>`}`,can?`确认扣除 ${price} 积分`:'积分不足，暂不可扩容',()=>{if(!can)return '积分不足，请先获取积分。';if(u.status!=='active'||u.points<price)return '账号状态或余额已变化，请重新打开确认。';const reference='Q-'+crypto.randomUUID().slice(0,8).toUpperCase();addLedger(u,'purchase',-price,'购买 1 个自动打卡名额',u.username,reference);u.purchased+=1;audit(u.id,'用户购买名额',`消耗 ${price} 积分，总名额增至 ${cap(u)} 个；${reference}`,u.username);save();render();if($('user-drawer').open)renderDrawer();$('action-dialog').innerHTML=`<div class="purchase-done"><div class="success-symbol">✓</div><h2 id="action-title">名额已增加</h2><p class="subtle">${esc(u.username)} 现在有 ${cap(u)} 个自动打卡名额</p><div class="purchase-summary"><div><span>已扣积分</span><strong>${price} 积分</strong></div><div><span>剩余积分</span><strong>${u.points} 积分</strong></div></div><p class="subtle">积分流水已记录，可以继续开启一个自动账号。</p><button class="primary" data-action="purchase-done">完成</button></div>`;modalSubmit=null;$('action-dialog').querySelector('button').focus();});if(!can)$('modal-confirm').disabled=true;
  }
  function securityModal(u,type){const reset=type==='recovery';modal(reset?'重置本站登录':'退出所有设备',`<p class="subtle">${esc(u.username)} · ${reset?'生成一次性重置凭证，由管理员交给用户本人。重置仅用于本站账号。':'使当前本站登录会话失效，下次访问需要重新登录。自动签到计划保持原样。'}</p>${reset?'<div class="notice">本原型只展示操作流程，生成的示例凭证不能用于真实登录。</div>':''}${reasonField()}`,reset?'生成示例凭证':'确认退出设备',data=>{const reason=String(data.get('reason')).trim();if(!reason)return '请填写操作原因。';audit(u.id,reset?'重置本站登录':'退出所有设备',reason);save();render();if($('user-drawer').open)renderDrawer();if(reset){$('action-dialog').innerHTML=`<div class="modal-head"><h2 id="action-title">示例重置凭证已生成</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><p class="subtle">用于展示管理员处理忘记密码的流程。</p><div class="notice"><strong>DEMO-${u.id}-RESET</strong><br>示例凭证 · 无真实登录效力</div><p class="subtle">正式接入时应设为一次使用、短期有效，用户自行设置新密码。</p><button class="primary" data-action="close-modal">完成</button>`;modalSubmit=null;}else{closeModal();toast('演示操作完成，已记录退出设备。');}});}
  function createModal(){modal('新增用户',`<p class="subtle">新用户默认获得 ${db.rules.free} 个免费名额、0 积分。创建后可在详情中发放积分。</p><label class="field-label" for="new-username">用户名</label><input id="new-username" name="username" pattern="[a-z0-9][a-z0-9_-]{2,31}" minlength="3" maxlength="32" required placeholder="3–32 位小写字母、数字或下划线" autocomplete="off"><label class="field-label" for="new-name">用户昵称</label><input id="new-name" name="name" maxlength="24" required placeholder="例如：小雨"><div class="notice" style="margin-top:18px">原型只创建演示用户。正式版本建议生成一次性激活凭证，由用户自行设置密码。</div>`,'创建演示用户',data=>{const name=String(data.get('name')).trim(),username=String(data.get('username')).trim();if(!/^[a-z0-9][a-z0-9_-]{2,31}$/.test(username))return '请填写有效的用户名。';if(db.users.some(u=>u.username===username))return '该用户名已存在。';if(!name)return '请填写昵称。';const u={id:Math.max(...db.users.map(x=>x.id),1000)+1,username,name,email:'',points:0,free:db.rules.free,purchased:0,status:'active',created:now(),last:now(),accounts:[],note:'',mail:false,push:false,success:true,failure:true};db.users.push(u);audit(u.id,'新增用户',`初始免费名额 ${u.free} 个，初始积分 0。`);closeModal();filter='all';search='';stateFilter='all';pageNum=1;refreshViews();openDrawer(u.id);toast('演示用户已创建。');});}
  function registrationModal(){const opening=!db.registration;modal(opening?'开放用户注册？':'关闭用户注册？',`<p class="subtle">${opening?`新用户可自行注册，获得 ${db.rules.free} 个免费自动打卡名额。`:'关闭后不再接受新用户注册。已有用户可以继续登录和使用自动打卡，管理员仍可新增用户。'}</p>`,opening?'确认开放':'确认关闭',()=>{db.registration=opening;audit(null,opening?'开放注册':'关闭注册','调整平台新用户注册入口。');closeModal();refreshViews();toast(opening?'注册已开放。':'注册已关闭，已有用户不受影响。');});}

  document.addEventListener('click',e=>{
    const el=e.target.closest('button,[data-detail]');if(!el)return;
    if(el.dataset.filter){filter=el.dataset.filter;pageNum=1;selected.clear();render();return;}
    if(el.dataset.detail){openDrawer(el.dataset.detail);return;}
    if(el.dataset.page){pageNum=Number(el.dataset.page);renderRows();return;}
    if(el.dataset.drawerTab){drawerTab=el.dataset.drawerTab;renderDrawer();return;}
    const u=user(el.dataset.user),action=el.dataset.action;
    if(action==='goto-rules'){location.hash='rules';}
    else if(action==='create')createModal();
    else if(action==='filter-all'||action==='filter-attention'){filter=action==='filter-all'?'all':'attention';pageNum=1;selected.clear();render();}
    else if(action==='clear-filters'){search='';filter='all';stateFilter='all';pageNum=1;render();}
    else if(action==='clear-selection'){selected.clear();renderRows();}
    else if(action==='close-drawer')closeDrawer();
    else if(action==='close-modal'||action==='purchase-done')closeModal();
    else if(action==='points'&&u)pointsModal([u.id]);
    else if(action==='bulk-points')pointsModal([...selected]);
    else if(action==='status'&&u)statusModal([u.id]);
    else if(action==='bulk-disable')statusModal([...selected]);
    else if(action==='quota'&&u)quotaModal(u);
    else if(action==='purchase'&&u)purchaseModal(u);
    else if(action==='add-demo-account'&&u){const a={id:'demo-'+crypto.randomUUID().slice(0,8),name:'新增账号 '+(u.accounts.length+1),channel:'龙湖 App',auto:false,state:'idle',signTime:'09:10',checkTime:'16:00'};u.accounts.push(a);audit(u.id,'添加演示签到账号',a.name+'，尚未开启自动打卡。');refreshViews();toast('已添加演示账号，可继续开启自动打卡。');}
    else if(action==='toggle-auto'&&u){const a=u.accounts.find(x=>x.id===el.dataset.account);if(!a||u.status==='disabled')return;if(!a.auto&&used(u)>=cap(u)){purchaseModal(u);return;}a.auto=!a.auto;if(a.auto&&a.state==='idle')a.state='pending';audit(u.id,a.auto?'开启演示自动打卡':'暂停演示自动打卡',a.name+'；积分未变动。');refreshViews();toast(a.auto?'已开启自动打卡，使用已有名额，未扣积分。':'已暂停自动打卡，名额可重复使用，积分余额不变。');}
    else if(action==='demo-purchase-default')purchaseModal(db.users.find(t=>t.status==='active'&&t.points>=db.rules.price)||db.users[0]);
    else if((action==='recovery'||action==='revoke')&&u)securityModal(u,action);
    else if(action==='registration')registrationModal();
    else if(el.id==='reset-demo')modal('恢复示例数据？','<p class="subtle">将清除本原型中的积分调整、名额购买和用户修改，恢复初始示例。真实用户数据不受影响。</p>','恢复示例',()=>{closeModal();if($('user-drawer').open)closeDrawer();db=seed();selected.clear();filter='all';search='';stateFilter='all';pageNum=1;save();render();toast('已恢复初始示例。');});
  });
  document.addEventListener('input',e=>{if(e.target.id==='user-search'){search=e.target.value;pageNum=1;selected.clear();renderRows();}if(e.target.id==='ledger-search')filterLedger();});
  document.addEventListener('change',e=>{
    if(e.target.id==='state-filter'){stateFilter=e.target.value;pageNum=1;selected.clear();renderRows();}
    if(e.target.id==='user-order'){order=e.target.value;pageNum=1;renderRows();}
    if(e.target.dataset.select){const id=Number(e.target.dataset.select);e.target.checked?selected.add(id):selected.delete(id);renderRows();}
    if(e.target.id==='select-page'){filteredUsers().slice((pageNum-1)*PAGE_SIZE,pageNum*PAGE_SIZE).forEach(u=>e.target.checked?selected.add(u.id):selected.delete(u.id));renderRows();}
    if(e.target.id==='ledger-type')filterLedger();
  });
  function filterLedger(){const query=$('ledger-search').value.toLowerCase(),type=$('ledger-type').value,rows=db.ledger.filter(r=>(type==='all'||r.type===type)&&(!query||[user(r.userId)?.username,r.reason,r.id].some(v=>String(v).toLowerCase().includes(query))));$('ledger-rows').innerHTML=ledgerRows([...rows]);$('ledger-empty').hidden=!!rows.length;}
  document.addEventListener('submit',e=>{
    if(e.target.id==='modal-form'){e.preventDefault();if(!modalSubmit)return;const error=modalSubmit(new FormData(e.target));if(error&&$('modal-error'))$('modal-error').textContent=error;}
    if(e.target.id==='note-form'){e.preventDefault();const u=user(drawerId),note=$('user-note').value.trim();if(u.note===note){toast('备注没有变化。');return;}u.note=note;audit(u.id,'更新管理员备注',note||'清空备注');refreshViews();toast('备注已保存。');}
    if(e.target.id==='rules-form'){e.preventDefault();const data=new FormData(e.target),free=Number(data.get('free')),price=Number(data.get('price'));if(!Number.isSafeInteger(free)||free<0||free>20||!Number.isSafeInteger(price)||price<1||price>10000){$('rules-error').textContent='请检查免费名额与扩容价格，填写范围内的整数。';return;}modal('保存权益规则？',`<p class="subtle">新用户免费名额：${db.rules.free} → <strong>${free} 个</strong><br>新增名额价格：${db.rules.price} → <strong>${price} 积分 / 个</strong></p><div class="notice">已有用户免费名额及已购名额保持原值，价格只应用于之后的购买。</div>`,'确认保存',()=>{const old=db.rules;db.rules={free,price};audit(null,'修改权益规则',`新用户免费 ${old.free} → ${free} 个，扩容价格 ${old.price} → ${price} 积分。`);closeModal();refreshViews();toast('权益规则已保存。');});}
  });
  $('user-drawer').addEventListener('cancel',()=>{drawerId=null;});
  $('action-dialog').addEventListener('close',()=>{modalSubmit=null;});
  function route(){const value=location.hash.slice(1);page=['users','ledger','rules','audit'].includes(value)?value:'users';selected.clear();render();}
  window.addEventListener('hashchange',route);
  document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
  route();
})();
